package com.yeyamo_mobile.api.discovery_service.infrastructure.web;
import jakarta.validation.Valid;import jakarta.validation.constraints.NotNull;import org.springframework.web.bind.annotation.*;import com.yeyamo_mobile.api.discovery_service.application.maps.*;
@RestController@RequestMapping("/api/v1/maps")public class MapsController{private final MapsService maps;public MapsController(MapsService maps){this.maps=maps;}@GetMapping("/geocode")public GeocodeResult geocode(@RequestParam String address){return maps.geocode(address);}@GetMapping("/reverse-geocode")public GeocodeResult reverse(@RequestParam double latitude,@RequestParam double longitude){return maps.reverse(latitude,longitude);}@PostMapping("/route")public RouteResult route(@Valid@RequestBody RouteRequest request){return maps.route(request.origin(),request.destination(),request.travelMode());}public record RouteRequest(@NotNull Coordinate origin,@NotNull Coordinate destination,TravelMode travelMode){}}
